select
  id, location, repair_user, repair_user_id, phone, rapair_name, remark, reservation_date, reservation_start_time, reservation_end_time, reservation_time, status, repair_status, is_door, repair_image, repair_end_image, repair_end_remark, create_time, update_time
from sys_repair_log


        and id = #{id}


        and location = #{location}


        and repair_user = #{repairUser}


        and repair_user_id = #{repairUserId}


        and phone = #{phone}


        and rapair_name = #{rapairName}


        and remark = #{remark}


        and reservation_date = #{reservationDate}


        and reservation_start_time = #{reservationStartTime}


        and reservation_end_time = #{reservationEndTime}


        and reservation_time = #{reservationTime}


        and status = #{status}


        and repair_status = #{repairStatus}


        and is_door = #{isDoor}


        and repair_image = #{repairImage}


        and repair_end_image = #{repairEndImage}


        and repair_end_remark = #{repairEndRemark}


        and create_time = #{createTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

